<?php
require_once __DIR__.'/config.php';
require_login();
$system=strtoupper(trim((string)($_GET['system']??'MAIFIP'))); if(!in_array($system,['AICS','MAIFIP'],true))$system='MAIFIP';
if(!fams_workspace_admin_allowed($system,'manage_usertypes')){http_response_code(403);exit('User-type management is not permitted for this workspace.');}
$catalog=fams_permission_catalog(); $error=''; $success='';
function fams_role_slug(string $label): string { $slug=strtolower(trim(preg_replace('/[^a-zA-Z0-9]+/','_', $label), '_')); return substr($slug,0,36) ?: 'custom_role'; }
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf(); $system=strtoupper((string)($_POST['system']??'MAIFIP')); if(!in_array($system,['AICS','MAIFIP'],true))$system='MAIFIP'; if(!fams_workspace_admin_allowed($system,'manage_usertypes')){http_response_code(403);exit('User-type management is not permitted for this workspace.');} $action=(string)($_POST['action']??'');
 try {
  if($action==='save'){
   $id=(int)($_POST['id']??0); $label=trim((string)($_POST['label']??'')); $base=(string)($_POST['base_role']??'staff'); $active=isset($_POST['is_active'])?1:0; $selected=array_fill_keys(array_map('strval',(array)($_POST['permissions']??[])),true);
   if($label===''||(function_exists('mb_strlen')?mb_strlen($label):strlen($label))>90)throw new RuntimeException('Enter a user type name of 1–90 characters.');
   $allowedBases=$system==='AICS'?['manager','staff','social_worker']:['manager','encoder','staff','social_worker'];
   if(!in_array($base,$allowedBases,true) && !($id>0 && $base==='admin'))throw new RuntimeException('Select a valid permission template. Administrator access cannot be assigned to custom user types.');
   foreach(array_keys($selected) as $key)if(!isset($catalog[$key]))unset($selected[$key]);
   $perms=[];foreach($catalog as $key=>$desc)$perms[$key]=isset($selected[$key]);
   if($id){$st=$pdo->prepare('SELECT * FROM fams_user_types WHERE id=? AND system_key=?');$st->execute([$id,$system]);$old=$st->fetch(PDO::FETCH_ASSOC);if(!$old)throw new RuntimeException('User type was not found.'); if($base==='admin' && !((int)$old['is_system']===1 && (string)$old['role_key']==='admin'))throw new RuntimeException('Administrator privileges cannot be assigned to custom user types.');
    if((int)$old['is_system']===1){$base=(string)$old['base_role'];$slug=(string)$old['role_key'];}
    else {$slug=(string)$old['role_key'];}
    $baseline=fams_default_type_permissions($system,$base); foreach($perms as $permKey=>$allowed) $perms[$permKey]=($allowed && !empty($baseline[$permKey]));
    if((int)$old['is_system']===1 && $slug==='admin'){$perms=array_fill_keys(array_keys($catalog),true);$active=1;}
    if($active===0){$table=$system==='AICS'?'aics_users':'users';$q=$pdo->prepare("SELECT COUNT(*) FROM `{$table}` WHERE role=? AND is_active=1");$q->execute([$slug]);if((int)$q->fetchColumn()>0)throw new RuntimeException('This type is assigned to active accounts. Reassign or disable those accounts first, then disable the type.');}
    $st=$pdo->prepare('UPDATE fams_user_types SET label=?,base_role=?,is_active=?,permissions_json=?,created_by=? WHERE id=? AND system_key=?');$st->execute([$label,$base,$active,json_encode($perms),current_user()['id']??null,$id,$system]);
    log_action($pdo,'UPDATE_USER_TYPE',"Updated {$system} user type {$slug} and authorization matrix.");$success='User type and authorization rules saved.';
   }else{
    $slug=strtolower($system).'_'.fams_role_slug($label); $slug=substr($slug,0,43);
    $baseline=fams_default_type_permissions($system,$base); foreach($perms as $permKey=>$allowed) $perms[$permKey]=($allowed && !empty($baseline[$permKey]));
    $exists=$pdo->prepare('SELECT COUNT(*) FROM fams_user_types WHERE system_key=? AND role_key=?');$candidate=$slug;$suffix=2;while(true){$exists->execute([$system,$candidate]);if(!(int)$exists->fetchColumn())break;$candidate=substr($slug,0,31).'_'.$suffix++;}$slug=$candidate;
    $pdo->prepare('INSERT INTO fams_user_types(system_key,role_key,label,base_role,is_system,is_active,permissions_json,created_by) VALUES(?,?,?,?,0,?,?,?)')->execute([$system,$slug,$label,$base,$active,json_encode($perms),current_user()['id']??null]);
    log_action($pdo,'CREATE_USER_TYPE',"Created {$system} user type {$slug}.");$success='New user type created. It can now be assigned to eligible accounts.';
   }
  } elseif($action==='toggle'){
   $id=(int)($_POST['id']??0);$st=$pdo->prepare('SELECT * FROM fams_user_types WHERE id=? AND system_key=?');$st->execute([$id,$system]);$r=$st->fetch(PDO::FETCH_ASSOC);if(!$r)throw new RuntimeException('User type was not found.');if((string)$r['role_key']==='admin')throw new RuntimeException('The administrator user type cannot be disabled.');
   $new=(int)$r['is_active']?0:1;
   $table=$system==='AICS'?'aics_users':'users';$q=$pdo->prepare("SELECT COUNT(*) FROM `{$table}` WHERE role=? AND is_active=1");$q->execute([$r['role_key']]);if($new===0&&(int)$q->fetchColumn()>0)throw new RuntimeException('This type is assigned to active accounts. Reassign or disable those accounts first, then disable the type.');
   $pdo->prepare('UPDATE fams_user_types SET is_active=? WHERE id=?')->execute([$new,$id]);log_action($pdo,'TOGGLE_USER_TYPE',"Set {$system} user type {$r['role_key']} active={$new}.");$success=$new?'User type enabled.':'User type disabled.';
  } elseif($action==='remove'){
   $id=(int)($_POST['id']??0);$st=$pdo->prepare('SELECT * FROM fams_user_types WHERE id=? AND system_key=?');$st->execute([$id,$system]);$r=$st->fetch(PDO::FETCH_ASSOC);if(!$r)throw new RuntimeException('User type was not found.');if((int)$r['is_system']===1)throw new RuntimeException('Built-in user types are protected and cannot be removed.');
   $table=$system==='AICS'?'aics_users':'users';$q=$pdo->prepare("SELECT COUNT(*) FROM `{$table}` WHERE role=?");$q->execute([$r['role_key']]);$assigned=(int)$q->fetchColumn();$otherTable=$system==='AICS'?'users':'aics_users';$q=$pdo->prepare("SELECT COUNT(*) FROM `{$otherTable}` WHERE role=?");$q->execute([$r['role_key']]);$assigned+=(int)$q->fetchColumn();if($assigned>0)throw new RuntimeException('This type is assigned to accounts in one or both workspaces. Reassign those accounts before removing the type.');
   $pdo->prepare('DELETE FROM fams_user_types WHERE id=?')->execute([$id]);log_action($pdo,'REMOVE_USER_TYPE',"Removed {$system} user type {$r['role_key']}.");$success='User type removed.';
  }
 }catch(Throwable $e){$error=$e->getMessage();}
}
$types=fams_list_user_types($pdo,$system,false);$editId=(int)($_GET['edit']??0);if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['id'])&&($_POST['action']??'')==='save')$editId=(int)$_POST['id'];
$edit=null;if($editId){foreach($types as $t)if((int)$t['id']===$editId)$edit=$t;}
$baseOptions=$system==='AICS'?['manager'=>'Manager','staff'=>'Staff','social_worker'=>'Social Worker']:['manager'=>'LPGMA Manager','encoder'=>'LPGMA Staff','staff'=>'Staff','social_worker'=>'Social Worker'];
$editPerms=$edit?json_decode((string)$edit['permissions_json'],true):[];if(!is_array($editPerms))$editPerms=[];
$pageTitle='User Types & Authorization';require __DIR__.'/partials/header.php';
?>
