<script>
(()=>{const base=document.getElementById('utBase');const boxes=[...document.querySelectorAll('input[name="permissions[]"]')];const protectedAdminType=<?=json_encode((bool)($edit&&(string)$edit['role_key']==='admin'))?>;const baselines=<?=json_encode(array_reduce(array_keys($baseOptions),function($out,$role)use($system){$out[$role]=fams_default_type_permissions($system,$role);return $out;},[]),JSON_UNESCAPED_SLASHES)?>;if(protectedAdminType)return;const sync=()=>{const matrix=baselines[base?.value]||{};boxes.forEach(box=>{const allowed=!!matrix[box.value];box.disabled=!allowed;if(!allowed)box.checked=false;});};base?.addEventListener('change',sync);sync();})();
</script>
